UPDATE "calendar_events" SET "recurrence_key" = "recurrence_id" || ';RANGE=THISANDFUTURE' WHERE "this_and_future" AND "recurrence_id" IS NOT NULL;--> statement-breakpoint
INSERT INTO "calendar_events" ("id", "user_id", "account_id", "subscription_id", "google_calendar_id", "remote_id", "remote_etag", "series_key", "uid", "recurrence_key", "recurrence_id", "this_and_future", "ends_series", "sequence", "dtstamp", "method", "status", "summary", "location", "description", "organizer", "attendees", "my_partstat", "my_email", "all_day", "starts_at", "ends_at", "recurring", "range_ends_at", "ics", "message_id", "thread_id", "created_at", "updated_at", "revision")
SELECT 'cev_' || md5(random()::text || "source"."id"), "source"."user_id", "source"."account_id", "source"."subscription_id", "source"."google_calendar_id", NULL, NULL, "source"."series_key", "source"."uid", "source"."recurrence_id", "source"."recurrence_id", false, false, "source"."sequence", "source"."dtstamp", "source"."method", 'cancelled', "source"."summary", "source"."location", "source"."description", "source"."organizer", "source"."attendees", "source"."my_partstat", "source"."my_email", "source"."all_day", "source"."starts_at", "source"."ends_at", false, "source"."ends_at" + CASE WHEN "source"."all_day" THEN interval '1 day' ELSE interval '0' END, "source"."ics", "source"."message_id", "source"."thread_id", "source"."created_at", "source"."updated_at", 1
FROM "calendar_events" AS "source"
WHERE "source"."this_and_future" AND "source"."recurrence_id" IS NOT NULL AND (
  (NOT "source"."ends_series" AND "source"."status" = 'cancelled' AND NOT EXISTS (SELECT 1 FROM "calendar_events" AS "master" WHERE "master"."series_key" = "source"."series_key" AND "master"."recurrence_key" = '' AND "master"."status" = 'cancelled'))
  OR ("source"."ends_series" AND "source"."range_sequence" IS NOT NULL AND ("source"."range_sequence" <> "source"."sequence" OR "source"."range_dtstamp" IS DISTINCT FROM "source"."dtstamp"))
);--> statement-breakpoint
UPDATE "calendar_events" SET "status" = CASE WHEN upper("ics") LIKE '%' || chr(10) || 'STATUS:TENTATIVE%' THEN 'tentative' ELSE 'confirmed' END, "method" = 'REQUEST', "sequence" = coalesce("range_sequence", "sequence"), "dtstamp" = CASE WHEN "range_sequence" IS NULL THEN "dtstamp" ELSE "range_dtstamp" END, "revision" = "revision" + 1
WHERE "this_and_future" AND NOT "ends_series" AND "status" = 'cancelled' AND "recurrence_id" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "calendar_events" AS "master" WHERE "master"."series_key" = "calendar_events"."series_key" AND "master"."recurrence_key" = '' AND "master"."status" = 'cancelled');--> statement-breakpoint
UPDATE "calendar_events" SET "sequence" = "range_sequence", "dtstamp" = "range_dtstamp", "revision" = "revision" + 1
WHERE "this_and_future" AND "ends_series" AND "range_sequence" IS NOT NULL AND ("range_sequence" <> "sequence" OR "range_dtstamp" IS DISTINCT FROM "dtstamp");--> statement-breakpoint
ALTER TABLE "calendar_events" DROP COLUMN "range_sequence";--> statement-breakpoint
ALTER TABLE "calendar_events" DROP COLUMN "range_dtstamp";
